const PostGroupController = require('./PostGroupController');

/**
 * Compatible entry point for the existing main.js flow
 * @param {Object} options Configuration block generated by main.js
 */
async function preparePostGroupDraft(options) {
  const controller = new PostGroupController();
  return await controller.prepareDraft(options);
}

module.exports = {
  PostGroupController,
  preparePostGroupDraft,
};
